import{_ as t,o as r,c as a,ah as s}from"./chunks/framework.ChH6X6u6.js";const p=JSON.parse(`{"title":"Page d'accueil","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/page-accueil.md","filePath":"src/guide/admin/page-accueil.md"}`),n={name:"guide/admin/page-accueil.md"};function i(o,e,l,u,c,g){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="page-d-accueil" tabindex="-1">Page d&#39;accueil <a class="header-anchor" href="#page-d-accueil" aria-label="Permalink to &quot;Page d&#39;accueil&quot;">​</a></h1><p>La page d&#39;accueil est ce que voient les familles et les visiteurs en arrivant sur l&#39;adresse de votre établissement, avant de se connecter. Elle se configure depuis <strong>Page d&#39;accueil</strong>, dans le menu de gauche, juste au-dessus de <strong>Paramètres de l&#39;application</strong>.</p><p>Elle peut contenir quatre parties :</p><table tabindex="0"><thead><tr><th>Partie</th><th>Contenu</th><th>Quand elle est affichée</th></tr></thead><tbody><tr><td><strong>En-tête</strong></td><td>Logo, accroche, sous-titre et boutons</td><td>Toujours</td></tr><tr><td><strong>Présentation</strong></td><td>Un titre, un texte et une image</td><td>Dès qu&#39;elle a du contenu, si <strong>Afficher</strong> est coché</td></tr><tr><td><strong>Départements</strong></td><td>Des cartes (titre, description, image) présentant votre offre</td><td>Dès qu&#39;elle contient une carte, si <strong>Afficher</strong> est coché</td></tr><tr><td><strong>Foire aux questions</strong></td><td>Des questions et leurs réponses, qui s&#39;ouvrent au clic</td><td>Dès qu&#39;elle contient une question, si <strong>Afficher</strong> est coché</td></tr></tbody></table><p>Le bouton <strong>Voir la page</strong>, en haut à droite, ouvre la page d&#39;accueil dans un nouvel onglet pour contrôler le résultat.</p><h2 id="ce-que-voient-les-visiteurs-tant-que-rien-n-est-configure" tabindex="-1">Ce que voient les visiteurs tant que rien n&#39;est configuré <a class="header-anchor" href="#ce-que-voient-les-visiteurs-tant-que-rien-n-est-configure" aria-label="Permalink to &quot;Ce que voient les visiteurs tant que rien n&#39;est configuré&quot;">​</a></h2><p>Une section vide n&#39;apparaît jamais : aucun texte d&#39;exemple n&#39;est montré aux familles. Sans configuration, la page se limite donc à l&#39;en-tête, avec votre logo, l&#39;accroche et deux boutons.</p><p>Tant qu&#39;aucune section n&#39;est affichée, un bandeau apparaît en haut de la page d&#39;accueil pour les <strong>administrateurs uniquement</strong> : « Votre page d&#39;accueil n&#39;affiche que l&#39;essentiel ». Son bouton <strong>Configurer</strong> mène à l&#39;éditeur. Les visiteurs ne le voient pas.</p><h2 id="suivre-l-etat-de-chaque-partie" tabindex="-1">Suivre l&#39;état de chaque partie <a class="header-anchor" href="#suivre-l-etat-de-chaque-partie" aria-label="Permalink to &quot;Suivre l&#39;état de chaque partie&quot;">​</a></h2><p>En haut de l&#39;éditeur, quatre vignettes résument l&#39;état de chaque partie ; le même état est rappelé en haut de chaque bloc :</p><ul><li><strong>Toujours affiché</strong> : l&#39;en-tête ;</li><li><strong>Affichée</strong> : la partie a du contenu et apparaît sur la page ;</li><li><strong>Masquée</strong> : la partie a du contenu, mais <strong>Afficher cette section sur la page</strong> est décoché ;</li><li><strong>Vide, non affichée</strong> : il n&#39;y a encore rien à montrer.</li></ul><p>Masquer une partie permet de la préparer tranquillement, par exemple rédiger toute la FAQ, avant de la publier en cochant la case.</p><h2 id="ecrire-dans-plusieurs-langues" tabindex="-1">Écrire dans plusieurs langues <a class="header-anchor" href="#ecrire-dans-plusieurs-langues" aria-label="Permalink to &quot;Écrire dans plusieurs langues&quot;">​</a></h2><p>Chaque texte se saisit une fois par langue de l&#39;application (les champs portent l&#39;étiquette <strong>FR</strong> ou <strong>EN</strong>). Vous pouvez n&#39;en remplir qu&#39;une : le visiteur qui consulte la page dans l&#39;autre langue voit alors ce texte-là plutôt qu&#39;une partie vide.</p><h2 id="en-tete" tabindex="-1">En-tête <a class="header-anchor" href="#en-tete" aria-label="Permalink to &quot;En-tête&quot;">​</a></h2><ul><li><strong>Logo</strong> : c&#39;est le logo de l&#39;établissement, le même que dans le menu. Il se change dans les paramètres (bouton <strong>Modifier le logo</strong>), voir <a href="/era-guide/guide/admin/parametres-application.html">Paramètres de l&#39;application</a>.</li><li><strong>Accroche</strong> et <strong>Sous-titre</strong> : les deux lignes affichées sous le logo. Laissez un champ vide pour garder le texte par défaut dans cette langue.</li><li><strong>Boutons</strong> : ils ne se configurent pas. <ul><li><strong>Inscrire mon enfant</strong> ouvre le formulaire d&#39;inscription en ligne. Les demandes envoyées arrivent au secrétariat, voir <a href="/era-guide/guide/secretariat/candidatures.html">Candidatures</a>.</li><li><strong>Se connecter</strong> mène à la page de connexion. Un utilisateur déjà connecté voit <strong>Mon espace</strong> à la place.</li></ul></li></ul><p>Cliquez sur <strong>Enregistrer les modifications</strong> pour appliquer l&#39;accroche et le sous-titre.</p><h2 id="presentation" tabindex="-1">Présentation <a class="header-anchor" href="#presentation" aria-label="Permalink to &quot;Présentation&quot;">​</a></h2><p>La partie où vous présentez l&#39;établissement : son histoire, son projet, ce qui le distingue.</p><ol><li>Cochez <strong>Afficher cette section sur la page</strong>.</li><li>Renseignez le <strong>Titre</strong> et le <strong>Texte</strong>. Laissez une ligne vide entre deux paragraphes.</li><li>Ajoutez éventuellement une <strong>Image</strong> avec <strong>Choisir une image</strong> : PNG, JPG ou WebP, 4 Mo maximum. Un format paysage rend mieux.</li><li>Cliquez sur <strong>Enregistrer les modifications</strong>.</li></ol><p>L&#39;image n&#39;est envoyée qu&#39;à l&#39;enregistrement. <strong>Remplacer</strong> en choisit une autre ; <strong>Retirer l&#39;image</strong> la supprime, là aussi au prochain enregistrement. Sans image, le texte s&#39;affiche centré sur toute la largeur.</p><h2 id="departements" tabindex="-1">Départements <a class="header-anchor" href="#departements" aria-label="Permalink to &quot;Départements&quot;">​</a></h2><p>Une carte par département, filière ou cycle. Les cartes sont <strong>libres</strong> : elles ne sont pas reliées aux départements de <a href="/era-guide/guide/admin/structure-etablissement.html">Structure de l&#39;établissement</a>. Vous pouvez donc présenter votre offre comme vous le souhaitez, par exemple une seule carte « Maternelle et primaire », ou une carte pour une option qui n&#39;est pas un département.</p><h3 id="ajouter-une-carte" tabindex="-1">Ajouter une carte <a class="header-anchor" href="#ajouter-une-carte" aria-label="Permalink to &quot;Ajouter une carte&quot;">​</a></h3><ol><li>Cliquez sur <strong>Ajouter une carte</strong>.</li><li>Renseignez le <strong>Titre</strong> (obligatoire, dans au moins une langue), la <strong>Description</strong> et, si vous le souhaitez, une <strong>Image</strong>.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Une carte sans image affiche la première lettre de son titre sur un fond aux couleurs de l&#39;établissement.</p><h3 id="organiser-les-cartes" tabindex="-1">Organiser les cartes <a class="header-anchor" href="#organiser-les-cartes" aria-label="Permalink to &quot;Organiser les cartes&quot;">​</a></h3><ul><li>Les flèches <strong>Monter</strong> et <strong>Descendre</strong> changent l&#39;ordre d&#39;affichage.</li><li><strong>Modifier</strong> rouvre la carte ; <strong>Supprimer</strong> la retire définitivement, avec son image.</li><li><strong>Titre de la section</strong> remplace « Nos départements » ; laissez-le vide pour garder ce titre.</li></ul><h2 id="foire-aux-questions" tabindex="-1">Foire aux questions <a class="header-anchor" href="#foire-aux-questions" aria-label="Permalink to &quot;Foire aux questions&quot;">​</a></h2><p>Les questions que les familles posent le plus souvent : horaires, cantine, modalités de paiement, démarches d&#39;inscription…</p><ol><li>Cliquez sur <strong>Ajouter une question</strong>.</li><li>Renseignez la <strong>Question</strong> et la <strong>Réponse</strong>, toutes deux obligatoires dans au moins une langue.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>Sur la page d&#39;accueil, seules les questions sont visibles ; la réponse s&#39;ouvre quand le visiteur clique dessus. Les flèches, <strong>Modifier</strong>, <strong>Supprimer</strong> et le <strong>Titre de la section</strong> fonctionnent comme pour les départements.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Les enregistrements sont immédiats : dès que vous cliquez sur <strong>Enregistrer</strong>, la page d&#39;accueil publique est à jour.</p></div>',33)])])}const h=t(n,[["render",i]]);export{p as __pageData,h as default};
